    [Fact]
    public void Generator_EmittedCompute_AddChild_ReturnsWhitelistedClaims()
    {
        const string source = @"
using Cosmos.EffectAlgebra;
public class Sample
{
    [EffectOverride(""r"")]
    public void AddChild(object x) { }
