        var compilation = MakeCompilationWithGenerator(source);
        Assert.False(compilation.GetDiagnostics().Any(d => d.Severity == DiagnosticSeverity.Error),
            "生成代码编译不得有错误：" + string.Join("\n", compilation.GetDiagnostics()));

